fn gcd_i(m: int, n: int) -> int {
    // Precondition: both m and n must be strictly greater than zero.
    assert!(m > 0 && n > 0, "gcd_i requires positive inputs");

    // We use the subtraction‐based Euclidean algorithm.
    // At every step, we subtract the smaller number from the larger one,
    // preserving positivity and ensuring termination.
    let mut a = m;
    let mut b = n;
    while a != b {
        if a > b {
            a -= b;
        } else {
            b -= a;
        }
    }
    // When a == b, that value is the GCD.
    a
}

